/* Apply verified final scores; never use in-progress scores as outcomes. */
(()=>{'use strict';let checking=false;const alias=t=>({WSH:'WSH',WAS:'WSH',LA:'LAR'}[t]||t);
async function updateResults(silent=false){if(checking||!data)return;checking=true;const buttons=[...document.querySelectorAll('[data-update-results]'),document.getElementById('refresh')].filter(Boolean);buttons.forEach(b=>{b.disabled=true;b.textContent='Checking results…'});try{const weeks=[...new Set(data.games.filter(g=>!g.done&&new Date(g.date).getTime()<Date.now()).map(g=>g.week))];const pending=[];await Promise.all(weeks.map(async week=>{const r=await fetch('https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?dates='+data.season+'&seasontype=2&week='+week+'&limit=1000',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Scores unavailable');const j=await r.json();if(!Array.isArray(j.events))throw Error('Invalid scoreboard');for(const e of j.events){const c=e.competitions?.[0];if(!c?.status?.type?.completed)continue;const g=data.games.find(x=>String(x.id)===String(e.id));if(!g||g.done)continue;const h=c.competitors.find(x=>x.homeAway==='home'),a=c.competitors.find(x=>x.homeAway==='away');if(!h||!a||alias(h.team.abbreviation)!==g.h||alias(a.team.abbreviation)!==g.a)continue;const hs=Number(h.score),as_=Number(a.score);if(!Number.isInteger(hs)||!Number.isInteger(as_)||hs<0||as_<0||h.score===''||a.score==='')continue;pending.push({g,hs,as_})}}));for(const {g,hs,as_} of pending)Object.assign(g,{done:true,hs,as_});if(pending.length){picks=normalizePicks(picks);undoStack=[];redoStack=[];document.getElementById('undo').disabled=true;document.getElementById('redo').disabled=true;baselineCache={};output=null;renderWeekNav();run()}const label='Results checked '+new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})+(pending.length?' · '+pending.length+' new final'+(pending.length===1?'':'s'):' · no new finals');document.getElementById('resultsStatus').textContent=label;if(!silent)toast(label)}catch(e){document.getElementById('resultsStatus').textContent='Could not check scores. Published results retained; try again.';if(!silent)toast('Results unavailable. Please try again.')}finally{checking=false;buttons.forEach(b=>{b.disabled=false;b.textContent='Update results & odds'})}}
document.querySelectorAll('[data-update-results]').forEach(b=>b.onclick=()=>updateResults());document.getElementById('refresh').onclick=()=>updateResults();let first=true;document.addEventListener('lab:update',()=>{if(first){first=false;updateResults(true)}});if(data){first=false;updateResults(true)}setInterval(()=>{if(!document.hidden)updateResults(true)},300000);
})();
